<template><view class="page"><view class="card"><view class="field"><text class="field-label">活动邀请码</text><input v-model="code" class="input code" maxlength="10" placeholder="输入10位邀请码" /></view><button class="primary-btn" @click="lookup">查询活动</button></view><view v-if="preview" class="card"><view class="section-title">{{ preview.title }}</view><view class="muted">📍 {{ preview.location }}</view><view class="muted">🕒 {{ displayTime(preview.startTime) }}</view><button class="primary-btn" @click="go">查看并报名</button></view></view></template>
<script setup lang="ts">import{ref}from'vue';import{api}from'@/services/api';import{displayTime}from'@/utils/time';const code=ref(''),preview=ref<any>(null);async function lookup(){if(code.value.length!==10)return uni.showToast({title:'请输入10位邀请码',icon:'none'});preview.value=await api(`/activities/invitations/${code.value.toUpperCase()}`)}function go(){uni.navigateTo({url:`/pages/activityDetail/activityDetail?id=${preview.value.id}&code=${code.value.toUpperCase()}`})}</script><style scoped>.code{text-transform:uppercase;letter-spacing:8rpx}</style>
